def remove_word_count(text: str) -> str:
    """
    删除类似（全文共998字）的结尾统计，包括前面的空格或回车
    """
    # 匹配：可能有空格/回车 + （全文共数字字）
    text = re.sub(r'[\s\r\n]*（全文共?约?\s*\d+\s*字）', '', text)
    return text


def verify_references_with_llm(reference: str, statements: List[str]) -> List[Dict[str, str]]:
    """
    使用LLM验证引用的准确性
    
    Args:
        reference: 参考资料内容
        statements: 需要验证的语句列表
    
    Returns:
        List[Dict[str, str]]: 验证结果列表，每个元素包含idx和result
    """
#     prompt_template = """你会看到一个参考资料和一个statement，请你判断statement中的数字在参考资料中是否有相同含义的数字，注意： 
#  判断判断statement中的数字是否在参考资料中有相同含义的数字： 
#  - 如果有相同含义的数字（数据接受四舍五入），返回supported 
#  - 如果没有相同含义的数字，返回unsupported 

#  你应该返回单个字符串，只能是supported、unsupported或unknown中的一个，不要输出任何其他内容。

#  下面是参考资料和statement： 
#  <reference> 
#  {reference} 
#  </reference> 

#  <statement> 
#  {statement} 
#  </statement> 

#  下面开始判断，直接输出结果字符串，不要输出任何闲聊或解释。"""
    prompt_template="""
    你会看到一个参考资料和一个statement，请判断statement中的数字与参考资料中的数字是否有相同含义。  
    - 如果数字具有相同的含义（允许四舍五入），返回 `supported`。
    - 如果数字含义不同，返回 `unsupported`。
    - 如果无法判断，返回 `unknown`。

    例子1：
    <reference>
    截至2020年底，全国832个贫困县全部摘帽，剩余贫困人口如期脱贫，已实现“两不愁三保障”全面覆盖。
    </reference>
    <statement>
    截至去年底，剩余的832个贫困县已经脱贫摘帽。
    </statement>
    输出：supported

    例子2：
    <reference>
    扶贫开发领导小组成员单位先后出台了40多项政策文件，帮助解决疫情带来的困境。
    </reference>
    <statement>
    该基地直接带动300人稳定就业，其中脱贫户占比达40%。
    </statement>
    输出：unsupported

    下面是参考资料和statement：  
    <reference>  
    {reference}  
    </reference>  
    <statement>  
    {statement}  
    </statement>  
    请不要输出 supported 或者 unsupported 或者 unknown 以外的任何内容，只能输出一个词
    开始判断：
    """
    # 只处理第一个statement
    if not statements:
        return [{"idx": 1, "result": "unknown"}]
    
    statement = statements[0]
    
    # 填充prompt
    prompt = prompt_template.format(
        reference=reference,
        statement=statement
    )
    logger.info(f"prompt:{prompt}")
    # 获取LLM
    llm = get_llm_by_type(AGENT_LLM_MAP.get("reporter", "default"))
    #llm = get_llm_by_type(AGENT_LLM_MAP.get("support_verifier", "default"))
    
    # 调用LLM
    try:
        response = llm.invoke(prompt)
        content = response.content.strip()
        logger.info(f"LLM返回结果: {content}")
        # 验证结果是否合法
        if content in ["supported", "unsupported", "unknown"]:
            return [{"idx": 1, "result": content}]
        else:
            # 结果不合法，返回unknown
            logger.error(f"LLM返回了非法结果: {content}")
            return [{"idx": 1, "result": "unknown"}]
    except Exception as e:
        logger.error(f"LLM验证引用失败: {str(e)}")
        # 失败时返回默认结果
        return [{"idx": 1, "result": "unknown"}]



@dataclass
class NumberBestMatch:
    text: str
    score: float
    clauseIndex: int
    span: int
    matchNumber: List[float]


CHINESE_NUMBERS = {
    "零":0,"一":1,"二":2,"三":3,"四":4,"五":5,
    "六":6,"七":7,"八":8,"九":9,
    "十":10,"百":100,"千":1000,"万":10000,"亿":100000000
}

ARABIC_UNIT_MULTIPLIER = {
    "十":10,"百":100,"千":1000,"万":10000,"亿":100000000
}


def is_boundary(ch: str):
    return ch in "。！？；;!?\n\r"


from typing import List

def split_to_clauses(text: str) -> List[str]:
    """
    报告文本切分：
    - 标题 (#) 截取到该行结束
    - 普通文本按句号切句
    - 保留原始换行
    """

    text = text.replace("\r\n", "\n")

    lines = text.splitlines(keepends=True)

    clauses = []

    for line in lines:

        stripped = line.strip()

        # 空行直接保留
        if not stripped:
            clauses.append(line)
            continue

        # Markdown标题：整行保留
        if stripped.startswith("#"):
            clauses.append(line)
            continue

        # 普通文本：按句子切
        sentences = re.split(r'(?<=[。！？])', line)

        for s in sentences:
            if s.strip():
                clauses.append(s)

    return clauses

def chinese_to_arabic(chinese: str) -> Optional[float]:

    if not chinese:
        return None

    parts = chinese.split("点")

    if len(parts) > 2:
        return None

    integer_part = parts[0]
    decimal_part = parts[1] if len(parts)==2 else ""

    integer_val = parse_chinese_integer(integer_part)

    if integer_val is None:
        return None

    decimal_val = parse_chinese_decimal(decimal_part) if decimal_part else 0
    if decimal_val is None:
        logger.info(f"integer_val{integer_val}")
        logger.info(f"decimal_val{decimal_val}")
        # print(f"integer_val{integer_val}")
        # print(f"decimal_val{decimal_val}")
        return None
    return integer_val + decimal_val


def parse_chinese_integer(chinese: str):

    if not chinese:
        return 0

    result = 0
    temp = 0

    for i,ch in enumerate(chinese):

        num = CHINESE_NUMBERS.get(ch)

        if num is None:
            return None

        if ch == "十":
            if i == 0:
                temp = 10
            else:
                temp *= 10

        elif ch in ["百","千","万","亿"]:
            if temp == 0:
                temp = num//10
            else:
                temp *= num

            result += temp
            temp = 0

        else:
            if temp == 0:
                temp = num
            else:
                temp += num

    result += temp
    return result


def parse_chinese_decimal(chinese):

    result = 0
    denominator = 10

    for ch in chinese:

        num = CHINESE_NUMBERS.get(ch)

        if num is None or num > 9:
            return None

        result += num/denominator
        denominator *= 10

    return result


def parse_arabic_like_number(raw: str):

    normalized = raw.replace(",","")

    m = re.match(r'^(\d+(?:\.\d+)?)([十百千万亿])?$', normalized)

    if not m:
        return None

    base = float(m.group(1))

    unit = m.group(2)

    multiplier = ARABIC_UNIT_MULTIPLIER.get(unit,1)

    return base * multiplier


def extract_numbers(text:str):

    numbers = []

    occupied = set()

    arabic_regex = r'(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?(?:[十百千万亿])?'

    for m in re.finditer(arabic_regex,text):

        val = parse_arabic_like_number(m.group())

        if val is not None:

            numbers.append({
                "value":val,
                "original":m.group(),
                "start":m.start(),
                "end":m.end()
            })

            for i in range(m.start(),m.end()):
                occupied.add(i)

    chinese_regex = r'[零一二三四五六七八九十百千万亿点]+'

    for m in re.finditer(chinese_regex,text):

        s,e = m.start(),m.end()

        if any(i in occupied for i in range(s,e)):
            continue

        val = chinese_to_arabic(m.group())

        if val is not None:
            numbers.append({
                "value":val,
                "original":m.group(),
                "start":s,
                "end":e
            })

    return numbers


def is_date_related(text,number):

    value = number["value"]

    after = text[number["end"]:number["end"]+1]

    if after=="年" and 1900<=value<=2099:
        return True

    if after=="月" and 1<=value<=12:
        return True

    if after in ["日","号"] and 1<=value<=31:
        return True

    return False


def find_best_number_excerpt(source:str,query:str,max_span=3,max_len=280):

    query_nums = extract_numbers(query)

    valid_query = [n for n in query_nums if len(n["original"])>=2 and not is_date_related(query,n)]

    if not valid_query:
        return None

    clauses = split_to_clauses(source)

    clause_numbers = [
        [n for n in extract_numbers(c) if len(n["original"])>=2 and not is_date_related(c,n)]
        for c in clauses
    ]

    best = None
    best_count = 0

    for i in range(len(clauses)):

        for span in range(1,min(max_span,len(clauses)-i)+1):

            text = "".join(clauses[i:i+span])

            numbers = []

            seen = set()

            for j in range(i,i+span):

                for n in clause_numbers[j]:

                    if n["value"] not in seen:
                        numbers.append(n)
                        seen.add(n["value"])

            match = 0
            matched = []

            for q in valid_query:

                for n in numbers:

                    if q["value"] == n["value"]:
                        match+=1
                        matched.append(n["value"])
                        break

            if match == len(valid_query):

                return NumberBestMatch(
                    text=text[:max_len],
                    score=1.0,
                    clauseIndex=i,
                    span=span,
                    matchNumber=matched
                )

            if match > best_count:

                best_count = match

                best = NumberBestMatch(
                    text=text[:max_len],
                    score=match/len(valid_query),
                    clauseIndex=i,
                    span=span,
                    matchNumber=matched
                )

    return best



def cite_verify_report(query,docs):
    try:
        query_clauses = split_to_clauses(query)

        # print("\n开始检索文档...\n")

        new_doc = []

        for q_idx, q in enumerate(query_clauses):

            # 1 提取引用
            refs = extract_refs(q)

            # 2 删除引用
            clean_q = remove_refs(q)

            # 3 判断是否有数字
            nums = extract_numbers(clean_q)

            # 标题不处理
            clean_q_strip = clean_q.strip()
            if clean_q_strip.startswith("#"):
                logger.info(f"title{q}")
                new_doc.append(q)
                continue
            
            #非数字问题
            if len(nums) == 0:
                # print("跳过句子:", clean_q)

                # 没有数字直接恢复引用
                #这个地方需要天津院开发
                #子卿的ngram暴力匹配确定区间后，进行 LLM 判断是否匹配
                if refs:
                    refs = dedup_refs(refs)
                    clean_q = clean_q + "".join([f"【{r}】" for r in refs])

                new_doc.append(clean_q)
                continue
            
            #数字问题


            matched_ref_text_map = {}
            matched_refs =[]
            for doc_id, doc in docs.items():

                content = doc["content"]

                result = find_best_number_excerpt(
                    source=content,
                    query=clean_q
                )

                if result and result.score > 0:
                    matched_ref_text_map[doc_id] = result.text
                    matched_refs.append(doc_id)

            # if len(matched_ref_text_map)==0:
            #     logger.info(f"没有成功匹配的clean_q{clean_q}")
            # else:
            #     matched_texts = list(matched_ref_text_map.values())
            #     if isinstance(matched_texts, list):
            #         clean_q = clean_q + "(" + ", ".join(map(str, matched_texts)) + ")"
            #     else:
            #         clean_q = clean_q + "(" + str(matched_texts) + ")"
            
            all_refs =  matched_refs#+refs
            
            all_refs = dedup_refs(all_refs)
            
            # 使用LLM验证引用的准确性，只保留有效的引用
            #如果数字都对不上，其他的更别说了
            valid_refs= all_refs
            valid_refs = []
            if all_refs:
                for ref in all_refs:
                    if ref in matched_ref_text_map:
                        # 构建statement
                        statement = clean_q.strip()
                        if statement:
                            # 调用LLM验证，使用匹配到的片段而不是全文
                            results = verify_references_with_llm(matched_ref_text_map[ref], [statement])
                            logger.info(f"results{results}")
                            if results and results[0].get("result") == "supported":
                                valid_refs.append(ref)
            
            # 如果有有效引用，添加到句子中；否则，不添加引用
            if valid_refs:
                logger.info(f"valid_refs{valid_refs}")
                clean_q = move_refs_before_punctuation(clean_q, valid_refs)
            # 没有有效引用，保持原句不变

            
            new_doc.append(clean_q)

        # 6 生成完整文档
        final_doc = "".join(new_doc)


        final_doc=remove_word_count(final_doc)
        
        logger.info("\n================ 最终文档 ================")
        logger.info(final_doc)
        return final_doc
    except Exception as e_outer:
        # 整个函数异常托底
        logger.error(f"cite_verify_report 执行失败: {e_outer}")
        return query  # 返回原始 query 作为最安全托底

